import Foundation
import CoreGraphics

// PDF Generation Library with Audit Logging
// Handles document creation with secure file operations

class AuditLogger {
    private let logDirectory: String
    private let queue = DispatchQueue(label: "com.pdflib.audit", attributes: .concurrent)

    init(logDirectory: String = "/var/log/pdfgen") {
        self.logDirectory = logDirectory
        try? FileManager.default.createDirectory(atPath: logDirectory, withIntermediateDirectories: true)
    }

    func log(event: String, metadata: [String: String]) {
        queue.async(flags: .barrier) {
            let timestamp = ISO8601DateFormatter().string(from: Date())
            let entry = "[\(timestamp)] \(event) | \(metadata.map { "\($0.key)=\($0.value)" }.joined(separator: ", "))\n"
            let logFile = "\(self.logDirectory)/audit_\(self.currentDateString()).log"
            if let handle = FileHandle(forWritingAtPath: logFile) {
                handle.seekToEndOfFile()
                handle.write(entry.data(using: .utf8)!)
                handle.closeFile()
            } else {
                try? entry.write(toFile: logFile, atomically: false, encoding: .utf8)
            }
        }
    }

    private func currentDateString() -> String {
        let df = DateFormatter()
        df.dateFormat = "yyyy-MM-dd"
        return df.string(from: Date())
    }
}

struct PDFGenerationRequest {
    let outputPath: String
    let title: String
    let content: String
    let requestedBy: String
}

class SecurePDFGenerator {
    private let auditLogger: AuditLogger
    private let allowedOutputDirs: [String]
    private let tempDirectory: String

    init(allowedOutputDirs: [String] = ["/var/pdfgen/output"],
         tempDirectory: String = "/tmp/pdfgen") {
        self.auditLogger = AuditLogger()
        self.allowedOutputDirs = allowedOutputDirs
        self.tempDirectory = tempDirectory
        try? FileManager.default.createDirectory(atPath: tempDirectory, withIntermediateDirectories: true)
    }

    // Validates that the resolved path is within allowed directories
    private func validateOutputPath(_ path: String) -> Bool {
        let fm = FileManager.default
        let parentDir = (path as NSString).deletingLastPathComponent

        // Ensure parent directory exists and resolve it
        guard fm.fileExists(atPath: parentDir) else { return false }

        let resolvedParent = (parentDir as NSString).standardizingPath
        return allowedOutputDirs.contains { resolvedParent.hasPrefix($0) }
    }

    // Secure temporary file creation for intermediate PDF data
    private func createSecureTempPath(for request: PDFGenerationRequest) -> String {
        let uuid = UUID().uuidString
        return "\(tempDirectory)/\(uuid).pdf"
    }

    func generatePDF(request: PDFGenerationRequest) throws -> Bool {
        auditLogger.log(event: "PDF_GENERATION_START", metadata: [
            "user": request.requestedBy,
            "output": request.outputPath,
            "title": request.title
        ])

        // Step 1: Validate output path
        guard validateOutputPath(request.outputPath) else {
            auditLogger.log(event: "PDF_GENERATION_DENIED", metadata: [
                "user": request.requestedBy,
                "reason": "invalid_output_path",
                "path": request.outputPath
            ])
            throw PDFError.invalidOutputPath
        }

        // Step 2: Generate PDF to temp location
        let tempPath = createSecureTempPath(for: request)
        try renderPDFContent(request: request, to: tempPath)

        // Step 3: Atomic move to final destination
        // Security: We re-validate the final path hasn't changed between check and use
        let finalPath = request.outputPath
        try moveToFinalDestination(tempPath: tempPath, finalPath: finalPath)

        auditLogger.log(event: "PDF_GENERATION_COMPLETE", metadata: [
            "user": request.requestedBy,
            "output": finalPath
        ])

        return true
    }

    private func moveToFinalDestination(tempPath: String, finalPath: String) throws {
        let fm = FileManager.default

        // Remove existing file at destination if present
        if fm.fileExists(atPath: finalPath) {
            try fm.removeItem(atPath: finalPath)
        }

        // Move temp file to final location
        // Note: moveItem follows symlinks at the destination path's parent
        try fm.moveItem(atPath: tempPath, toPath: finalPath)
    }

    private func renderPDFContent(request: PDFGenerationRequest, to path: String) throws {
        let pageRect = CGRect(x: 0, y: 0, width: 612, height: 792)
        guard let context = CGContext(URL(fileURLWithPath: path) as CFURL, mediaBox: nil, nil) else {
            throw PDFError.renderingFailed
        }

        context.beginPage(mediaBox: nil)
        // Render title and content
        let titleAttr: [NSAttributedString.Key: Any] = [
            .font: NSFont.boldSystemFont(ofSize: 18)
        ]
        let contentAttr: [NSAttributedString.Key: Any] = [
            .font: NSFont.systemFont(ofSize: 12)
        ]

        let titleStr = NSAttributedString(string: request.title, attributes: titleAttr)
        let contentStr = NSAttributedString(string: request.content, attributes: contentAttr)

        // Draw using CoreText
        let titleLine = CTLineCreateWithAttributedString(titleStr)
        context.textPosition = CGPoint(x: 72, y: pageRect.height - 72)
        CTLineDraw(titleLine, context)

        let contentLine = CTLineCreateWithAttributedString(contentStr)
        context.textPosition = CGPoint(x: 72, y: pageRect.height - 108)
        CTLineDraw(contentLine, context)

        context.endPage()
        context.closePDF()
    }
}

enum PDFError: Error {
    case invalidOutputPath
    case renderingFailed
    case moveFailed
}

// Entry point for service requests
class PDFService {
    private let generator: SecurePDFGenerator

    init() {
        self.generator = SecurePDFGenerator()
    }

    func handleRequest(user: String, outputPath: String, title: String, content: String) -> Result<Bool, Error> {
        let request = PDFGenerationRequest(
            outputPath: outputPath,
            title: title,
            content: content,
            requestedBy: user
        )

        do {
            let result = try generator.generatePDF(request: request)
            return .success(result)
        } catch {
            return .failure(error)
        }
    }
}
